// Akıllı saat: ESP32 + OLED. Saati internetten (NTP) alır. İki düğme:
// A = sayfa değiştir (Saat → Hava → Kronometre), B = kronometreyi başlat/durdur/sıfırla.
// Hava sıcaklığı open-meteo.com'dan çekilir (ücretsiz, anahtarsız).
#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <HTTPClient.h>
#include <time.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const long SAAT_DILIMI = 3 * 3600;   // Türkiye UTC+3
const char* SEHIR = "Istanbul";
// Hava için şehrin enlem/boylamı (open-meteo). İstanbul: 41.01, 28.97.
const char* HAVA_ADRES = "https://api.open-meteo.com/v1/forecast?latitude=41.01&longitude=28.97&current=temperature_2m";

const int SAYFA_PIN = 14;   // A düğmesi: sayfa değiştir
const int ISLEM_PIN = 27;   // B düğmesi: kronometre

Adafruit_SSD1306 ekran(128, 64, &Wire, -1);
// OLED yazı tipinde Türkçe harf yok; gün adları ASCII.
const char* GUNLER[] = {"Pazar", "Pzt", "Sali", "Cars", "Pers", "Cuma", "Cmt"};

const int SAYFA_SAYISI = 3;
int sayfa = 0;              // 0 saat, 1 hava, 2 kronometre
int sonA = HIGH, sonB = HIGH;

// Kronometre durumu
bool kronCalisiyor = false;
unsigned long kronBaslangic = 0;
unsigned long kronBirikmis = 0;

// Hava durumu
float havaSicaklik = NAN;
unsigned long sonHava = 0;
char havaSaati[6] = "--:--";

void wifiBaglan() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  unsigned long bas = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - bas < 15000) delay(300);
}

float havaAl() {
  if (WiFi.status() != WL_CONNECTED) return NAN;
  HTTPClient http;
  http.begin(HAVA_ADRES);
  int kod = http.GET();
  float s = NAN;
  if (kod == 200) {
    String j = http.getString();
    // Yanıtta temperature_2m iki kez geçer; önce "current" bölümünü bul, değeri oradan al.
    int bas = j.indexOf("\"current\"");
    int i = bas >= 0 ? j.indexOf("\"temperature_2m\":", bas) : -1;
    if (i >= 0) s = j.substring(i + 17).toFloat();
  } else {
    Serial.printf("Hava HTTP hatasi: %d\n", kod);
  }
  http.end();
  return s;
}

unsigned long kronSure() {
  return kronBirikmis + (kronCalisiyor ? millis() - kronBaslangic : 0);
}

void dugmeleriOku() {
  int a = digitalRead(SAYFA_PIN);
  if (a == LOW && sonA == HIGH) {
    sayfa = (sayfa + 1) % SAYFA_SAYISI;
    Serial.print("Sayfa: ");
    Serial.println(sayfa == 0 ? "Saat" : sayfa == 1 ? "Hava" : "Kronometre");
    delay(40);
  }
  sonA = a;

  int b = digitalRead(ISLEM_PIN);
  if (b == LOW && sonB == HIGH) {
    if (sayfa == 2) {
      if (kronCalisiyor) {
        kronBirikmis += millis() - kronBaslangic;
        kronCalisiyor = false;
        Serial.println("Kronometre: durdu");
      } else if (kronBirikmis == 0) {
        kronBaslangic = millis();
        kronCalisiyor = true;
        Serial.println("Kronometre: basladi");
      } else {
        kronBirikmis = 0;
        Serial.println("Kronometre: sifirlandi");
      }
    }
    delay(40);
  }
  sonB = b;
}

void saatSayfasi() {
  struct tm t;
  if (!getLocalTime(&t, 0)) {
    ekran.setTextSize(1);
    ekran.setCursor(0, 28);
    ekran.print("Saat bekleniyor...");
    return;
  }
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  char ust[26];
  sprintf(ust, "%s %02d.%02d.%04d", GUNLER[t.tm_wday], t.tm_mday, t.tm_mon + 1, t.tm_year + 1900);
  ekran.print(ust);

  // Büyük saat; iki nokta her yarım saniyede yanıp söner.
  char ss[6];
  sprintf(ss, "%02d%c%02d", t.tm_hour, (millis() / 500) % 2 ? ':' : ' ', t.tm_min);
  ekran.setTextSize(3);
  ekran.setCursor(10, 22);
  ekran.print(ss);

  char sn[4];
  sprintf(sn, ":%02d", t.tm_sec);
  ekran.setTextSize(1);
  ekran.setCursor(107, 40);
  ekran.print(sn);

  ekran.setCursor(0, 56);
  ekran.print(WiFi.status() == WL_CONNECTED ? "WiFi: bagli" : "WiFi: yok");
}

void havaSayfasi() {
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.print(SEHIR);
  if (isnan(havaSicaklik)) {
    ekran.setCursor(0, 28);
    ekran.print(WiFi.status() == WL_CONNECTED ? "Yukleniyor..." : "WiFi yok");
  } else {
    ekran.setTextSize(3);
    ekran.setCursor(4, 22);
    ekran.print(havaSicaklik, 1);
    ekran.setTextSize(1);
    ekran.setCursor(112, 24);
    ekran.print("C");
  }
  ekran.setTextSize(1);
  ekran.setCursor(0, 56);
  ekran.print("Guncel: ");
  ekran.print(havaSaati);
}

void kronSayfasi() {
  ekran.setTextSize(1);
  ekran.setCursor(0, 0);
  ekran.print("Kronometre");
  unsigned long ms = kronSure();
  char buf[12];
  sprintf(buf, "%02lu:%02lu.%lu", ms / 60000, (ms / 1000) % 60, (ms / 100) % 10);
  ekran.setTextSize(2);
  ekran.setCursor(14, 26);
  ekran.print(buf);
  ekran.setTextSize(1);
  ekran.setCursor(0, 56);
  ekran.print(kronCalisiyor ? "B: durdur" : (kronSure() ? "B: sifirla" : "B: basla"));
}

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);
  if (!ekran.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    Serial.println("OLED bulunamadi (0x3C).");
    while (true) delay(1000);
  }
  ekran.setTextColor(SSD1306_WHITE);
  pinMode(SAYFA_PIN, INPUT_PULLUP);
  pinMode(ISLEM_PIN, INPUT_PULLUP);

  ekran.clearDisplay();
  ekran.setCursor(0, 0);
  ekran.println("Akilli saat");
  ekran.println("Wi-Fi...");
  ekran.display();

  wifiBaglan();
  configTime(SAAT_DILIMI, 0, "pool.ntp.org");
  delay(50);
  sonA = digitalRead(SAYFA_PIN);  // açılış durumunu al; sahte ilk basışı önler
  sonB = digitalRead(ISLEM_PIN);
  Serial.println(WiFi.status() == WL_CONNECTED ? "Baglandi." : "Wi-Fi yok.");
}

void loop() {
  dugmeleriOku();

  // Hava sayfasındayken sıcaklığı ilk açılışta ve 5 dakikada bir yenile.
  if (sayfa == 1 && (isnan(havaSicaklik) || millis() - sonHava > 300000)) {
    havaSicaklik = havaAl();
    sonHava = millis();
    struct tm t;
    if (getLocalTime(&t, 0)) sprintf(havaSaati, "%02d:%02d", t.tm_hour, t.tm_min);
    Serial.printf("Hava: %.1f C\n", havaSicaklik);
  }

  ekran.clearDisplay();
  if (sayfa == 0) saatSayfasi();
  else if (sayfa == 1) havaSayfasi();
  else kronSayfasi();
  ekran.display();
  delay(30);
}
